///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchIsuInfoChgList
 * @description search Isu Info Chg List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchIsuInfoChgList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchIsuInfoChgList",
        method: "post",
        action: action ?? "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList",
        ref: "dma_searchIsuInfoChgListReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function (action) {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: action ?? "/amount/amount.do?method=saveAddListing",
        ref: "dma_saveReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name searchIsuInfoChgList
 * @description search Isu Info Chg List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchIsuInfoChgList = async function () {
    await scwin.tx_fn_searchIsuInfoChgList('/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList');
};

/**
 * @method
 * @name calcListAmt
 * @description calc List Amt 처리
 * @returns {void}
 * @hidden N
 */
scwin.calcListAmt = function () {
    const addIsuAmt = $c.util.getComponent('ipt_addIsuAmt').getValue().replace(/\,/g, '');
    const bfchgListAmt = $c.util.getComponent('ipt_bfchgListAmt').getValue().replace(/\,/g, '');
    let afchgListAmt = "";
    if ((addIsuAmt != null && addIsuAmt !== "") && (bfchgListAmt != null && bfchgListAmt !== "")) {
        afchgListAmt = parseInt(bfchgListAmt) + parseInt(addIsuAmt);
    }
    if (afchgListAmt > 0) {
        $c.util.getComponent("ipt_afchgListAmt").setValue($c.num.formatMoney(afchgListAmt + ''));
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("apctTelNo", $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("apctFaxNo", $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("encrypApctEmail", $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    await scwin.tx_fn_save('/amount/amount.do?method=saveAddListing');
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('cal_addIsuDd').getValue()) === 0) {
                await $c.win.alert("추가발행일을 입력하십시오.");
                $c.util.getComponent("cal_addIsuDd").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_addIsuAmt').getValue()) === 0) {
                    await $c.win.alert("추가발행금액을 입력하십시오.");
                    $c.util.getComponent("ipt_addIsuAmt").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) === 0) {
                        await $c.win.alert("낙찰금리를 입력하십시오.");
                        $c.util.getComponent("ipt_coupnRt").focus();
                        return false;
                    } else {
                        if (fn_minusCheck($c.util.getComponent('ipt_coupnRt'), "낙찰금리") === "N") {
                            return false;
                        } else {
                            if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                                return false;
                            } else {
                                if (!CheckReqInfo(fm)) {
                                    return false;
                                } else {
                                    if (!await scwin.CheckReqInfo_Cellphone(fm)) {
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

