    $c.util.getComponent("cal_addIsuDd").setValue("");
    $c.util.getComponent("ipt_addIsuAmt").setValue("");
    $c.util.getComponent("ipt_coupnRt").setValue("");
    $c.util.getComponent("ipt_afchgListAmt").setValue("");
    ($c.util.getComponent("txt_addIsuAmtKor") && $c.util.getComponent("txt_addIsuAmtKor").setValue) ? $c.util.getComponent("txt_addIsuAmtKor").setValue("") : (($c.util.getComponent("txt_addIsuAmtKor") && $c.util.getComponent("txt_addIsuAmtKor").setText) ? $c.util.getComponent("txt_addIsuAmtKor").setText("") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_addIsuAmtKor"), void ("")));
};
